{"arguments": {"content": "#!/usr/bin/env python3
"""Calculate yearly production totals and write them into table J39:O53.

The table contains three agent categories (PE, GS, CC), each with Rentals,
Sales and Commercial sub-totals. Each sub-row should contain annual totals
based on the closing dates in column F, restricted to agents whose H column
matches the category and dates falling within each calendar year span defined
by the header dates (year starts) in the corresponding header row.

Data ranges:
  Rentals    : rows 8..37
  Sales      : rows 41..58
  Commercial : rows 62..74

Yearly total cells (J39:O53 layout):
  PE  : Rentals=K40:O40, Sales=K41:O41, Commercial=K42:O42
  GS  : Rentals=K45:O45, Sales=K46:O46, Commercial=K47:O47
  CC  : Rentals=K50:O50, Sales=K51:O51, Commercial=K52:O52
Year-start date headers live in rows 43, 48 and 53 for the three sections.
"""
import re
import sys
from datetime import datetime, timedelta

import openpyxl

EPOCH = datetime(1899, 12, 30)


def to_date(value):
    if isinstance(value, (int, float)):
        return (EPOCH + timedelta(days=value)).date()
    if isinstance(value, datetime):
        return value.date()
    return None


def calc_c(ws, row):
    """Compute the numeric value of the Commission (column C) cell."""
    c = ws.cell(row=row, column=3).value
    if c is None:
        return 0.0
    if isinstance(c, (int, float)):
        return float(c)
    s = str(c).strip()
    if not s.startswith("="):
        try:
            return float(s)
        except ValueError:
            return 0.0
    expr = s[1:]

    def repl(m):
        r = int(m.group(1))
        b = ws.cell(row=r, column=2).value or 0
        return str(b)

    expr = re.sub(r"B(\d+)", repl, expr)
    try:
        return float(eval(expr))
    except Exception:
        return 0.0


def compute_table(wb):
    ws = wb["Total (2)"]

    # (rentals_row, sales_row, commercial_row) for each agent category section
    data_blocks = [(40, 41, 42), (45, 46, 47), (50, 51, 52)]
    agent_maps = [("PE",), ("GS",), ("CC",)]
    data_ranges = [range(8, 38), range(41, 59), range(62, 75)]
    header_rows = [43, 48, 53]
    columns = list(range(11, 16))  # K..O

    results = {}
    for bi, (rent, sa, com) in enumerate(data_blocks):
        agents = agent_maps[bi]
        header_row = header_rows[bi]
        row_dates = [to_date(ws.cell(row=header_row, column=col).value)
                     for col in columns]

        for ri, rng in enumerate(data_ranges):
            target = (rent, sa, com)[ri]
            for ci, col in enumerate(columns):
                start = row_dates[ci]
                if ci + 1 < len(columns):
                    end = row_dates[ci + 1]
                elif start is not None:
                    end = datetime(start.year + 1, start.month,
                                   start.day).date()
                else:
                    end = None

                total = 0.0
                for r in rng:
                    h = ws.cell(row=r, column=8).value
                    if h is None:
                        continue
                    if not any(a in str(h) for a in agents):
                        continue
                    f = to_date(ws.cell(row=r, column=6).value)
                    if f is None:
                        continue
                    if start is not None and f >= start and \
                            (end is None or f < end):
                        total += calc_c(ws, r)
                results[(col, target)] = total
    return results


def main():
    input_path = sys.argv[1]
    output_path = sys.argv[2]

    wb = openpyxl.load_workbook(input_path, data_only=False)
    results = compute_table(wb)

    ws = wb["Total (2)"]
    for (col, target), value in results.items():
        cell = ws.cell(row=target, column=col)
        # Only overwrite the formerly-formula data cells with numeric totals.
        cell.value = value

    wb.save(output_path)


if __name__ == "__main__":
    main()", "path": "/bench/answers/47766/solution.py"}, "name": "write"}
